// packages/shell/src/config/android-config.ts
export const ANDROID_PERMISSIONS: readonly string[] = ["android.permission.INTERNET"];

export const BLOCKED_ANDROID_PERMISSIONS: readonly string[] = [
  "android.permission.READ_EXTERNAL_STORAGE",
  "android.permission.RECORD_AUDIO",
];

export function androidConfig(): Record<string, unknown> {
  return { permissions: [...ANDROID_PERMISSIONS], extra: [...BLOCKED_ANDROID_PERMISSIONS] };
}
